using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class TimelineEditorOperations
{
    private static T NewScript<T>(string path) where T:GodotObject=>GD.Load<GDScript>(path).New().AsGodotObject() as T??throw new InvalidOperationException(path);
    private static Button MakeButton(Control parent,string text,Action action){var button=new Button{Text=text};button.Pressed+=action;parent.AddChild(button);return button;}
    public StyleBoxFlat box(Color background,Color border){var style=new StyleBoxFlat{BgColor=background,BorderColor=border,ContentMarginLeft=10,ContentMarginRight=10,ContentMarginTop=1,ContentMarginBottom=1};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(6);return style;}
    public void apply_theme(Control owner){var theme=new Theme{DefaultFontSize=13};owner.Theme=theme;owner.AddThemeConstantOverride("separation",3);foreach(string type in new[]{"Button","MenuButton"}){theme.SetStylebox("normal",type,box(new Color("2a3849"),new Color("42546a")));theme.SetStylebox("hover",type,box(new Color("3a5065"),new Color("7493ad")));theme.SetStylebox("pressed",type,box(new Color("214f50"),new Color("80dbc4")));theme.SetStylebox("disabled",type,box(new Color("232c38"),new Color("303e4e")));var focus=box(Colors.Transparent,new Color("80dbc4"));focus.DrawCenter=false;theme.SetStylebox("focus",type,focus);theme.SetColor("font_color",type,new Color("e3edf7"));theme.SetColor("font_disabled_color",type,new Color("65788d"));}theme.SetStylebox("normal","LineEdit",box(new Color("151f2b"),new Color("42546a")));theme.SetColor("font_color","Label",new Color("b9cbdc"));}
    public void style_context_menu(Control owner){var menu=owner.Get("context_menu").As<PopupMenu>();menu.MinSize=new Vector2I(245,0);var panel=box(new Color("17212d"),new Color("4b6075"));panel.SetCornerRadiusAll(9);panel.ShadowColor=new Color(0,0,0,.38f);panel.ShadowSize=8;panel.SetContentMarginAll(7);menu.AddThemeStyleboxOverride("panel",panel);var hover=box(new Color("294c54"),new Color("5fa99a"));hover.SetCornerRadiusAll(5);hover.ContentMarginTop=5;hover.ContentMarginBottom=5;menu.AddThemeStyleboxOverride("hover",hover);foreach(var entry in new[]{("font_color","dce8f3"),("font_hover_color","ffffff"),("font_disabled_color","7f95a8"),("font_separator_color","7890a5")})menu.AddThemeColorOverride(entry.Item1,new Color(entry.Item2));foreach(var entry in new[]{("item_start_padding",12),("item_end_padding",16),("v_separation",5),("separator_height",10),("icon_max_width",20)})menu.AddThemeConstantOverride(entry.Item1,entry.Item2);menu.AddThemeFontSizeOverride("font_size",13);}
    public SpinBox timing_input(Control parent,string text){var label=new Label{Text=text};label.AddThemeFontSizeOverride("font_size",9);label.AddThemeColorOverride("font_color",new Color("82a7bc"));parent.AddChild(label);var input=new DragNumber();input.MinValue=0;input.MaxValue=86400;input.AllowGreater=true;input.Step=.01;input.Suffix=" s";input.CustomMinimumSize=new Vector2(92,0);input.SizeFlagsVertical=Control.SizeFlags.ShrinkCenter;input.UpdateOnTextChanged=false;input.GetLineEdit().AddThemeColorOverride("font_color",new Color("e2f2f7"));parent.AddChild(input);return input;}
    public HSlider zoom_slider(Control parent,string axis,double minimum,double maximum,double initial,string tooltip){var badge=new Label{Text=axis,CustomMinimumSize=new Vector2(18,18),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};badge.AddThemeColorOverride("font_color",new Color("83dfc8"));badge.AddThemeFontSizeOverride("font_size",10);parent.AddChild(badge);var slider=new HSlider{MinValue=minimum,MaxValue=maximum,Value=initial,Step=1,CustomMinimumSize=new Vector2(68,0),TooltipText=tooltip};parent.AddChild(slider);return slider;}
    private readonly Dictionary<string,Texture2D> _toolbarIcons=new();
    public Texture2D toolbar_icon(string kind){if(_toolbarIcons.TryGetValue(kind,out var texture))return texture;string path=IconPaths.TryGetValue(kind,out var source)?source:IconPaths["add"];string svg="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\"><g fill=\"none\" stroke=\""+(kind=="stop"?"#ff8291":"#94dfc6")+"\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">"+path+"</g></svg>";using var image=new Image();image.LoadSvgFromString(svg);texture=ImageTexture.CreateFromImage(image);_toolbarIcons[kind]=texture;return texture;}
}
